import { Activity, AlertTriangle, ArrowUpRight, Clock3, Cpu, Database, Gauge, HardDrive, MemoryStick, RefreshCw, Server, ShieldCheck, UsersRound } from 'lucide-react-native';
import { useCallback, useEffect, useMemo, useState } from 'react';
import type { ReactNode } from 'react';
import { ActivityIndicator, Platform, Pressable, ScrollView, StyleSheet, Text, View, useWindowDimensions } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { apiFetch as fetch, apiUrl, readApiError } from '../api/client';
import type { Account } from '../types';

type LoadState = 'loading' | 'ready' | 'unauthorized' | 'forbidden' | 'error';
type AdminAccount = Pick<Account, 'id' | 'username' | 'name' | 'role'>;
type PerformanceIssue = { id: string; severity: 'critical' | 'warning' | 'opportunity'; title: string; evidence: string; recommendation: string; score: number; confidence: 'high' | 'medium' };
type ClientMetricName = 'CLS' | 'FCP' | 'INP' | 'LCP' | 'TTFB' | 'API_DURATION' | 'LONG_TASK' | 'JS_HEAP_USED_MB' | 'JS_HEAP_USAGE' | 'IMAGE_TRANSFER_BYTES' | 'SCRIPT_TRANSFER_BYTES' | 'RENDER_RATE' | 'REQUEST_BURST' | 'FRAME_TIME';
type Monitoring = {
  generatedAt: string;
  requests: {
    active: number; rpm: number; lastMinute: number; errorsLastFiveMinutes: number; errorRate: number;
    p50Ms: number; p95Ms: number; p99Ms: number;
    buckets: Array<{ at: string; requests: number; errors: number; averageMs: number }>;
    endpoints: Array<{ method: string; route: string; requests: number; errors: number; averageMs: number; p95Ms: number; averageBytes: number; p95Bytes: number; compressedRate: number; uniqueClients: number; duplicateRequests: number; duplicateRate: number; totalTimeMs: number; topScreen: string }>;
    issues: PerformanceIssue[];
    diagnosticRequests: Array<{ at: number; occurredAt: string; method: string; route: string; status: number; durationMs: number; screen: string; requestId: string }>;
  };
  client: {
    windowMinutes: number; totalSamples: number;
    metrics: Array<{ name: ClientMetricName; samples: number; p75: number; poor: number }>;
    screens: Array<{ screen: string; name: Exclude<ClientMetricName, 'API_DURATION'>; detail: string | null; samples: number; p75: number; poor: number }>;
    apiRoutes: Array<{ route: string; samples: number; averageMs: number; p75Ms: number; p95Ms: number; poor: number; errors: number; topScreen: string }>;
  };
  analysis: { issues: PerformanceIssue[]; windowNote: string; sqlQueries: Array<{ queryId: string; query: string; calls: number; totalMs: number; meanMs: number; rows: number; sharedHits: number; sharedReads: number; tempWritten: number }> };
  alerts: { available: boolean; firing: number; pending: number; items: Array<{ name: string; severity: 'critical' | 'warning'; state: 'firing' | 'pending'; summary: string; activeAt: string | null; value: string | null }> };
  slo: {
    available: boolean; objective: number; latencyObjective: number; latencyTargetMs: number; retentionDays: number;
    windows: Array<{ range: string; label: string; samples: number; errors: number; availability: number | null; latencyCompliance: number | null; burnRate: number; budgetConsumedPercent: number; budgetRemainingPercent: number }>;
    incidents: Array<{ name: string; severity: 'critical' | 'warning'; startedAt: string; endedAt: string | null; durationMinutes: number }>;
  };
  logs: { available: boolean; retentionDays: number; services: string[] };
  traces: { available: boolean; retentionDays: number; recentTraces: number };
  infrastructure: {
    available: boolean; latencyMs: number;
    redis: { memoryUsedBytes: number; memoryPeakBytes: number; maxMemoryBytes: number; evictedKeys: number; rejectedConnections: number; connectedClients: number };
    queue: { waiting: number; active: number; delayed: number; failed: number; completed: number; paused: number; workers: number; oldestPendingSeconds: number; recentSampleSize: number; durationP95Ms: number; durationAverageMs: number; failedLast24Hours: number };
    realtime: { available: boolean; connections: number; authenticatedAccounts: number; rooms: number };
    outbox: { listenerConnected: boolean; notificationCount: number; dispatchRuns: number; fallbackRuns: number; lastNotificationAt: string | null; lastDispatchAt: string | null; nextWakeAt: string | null };
  };
  media: { processing: number; ready: number; failed: number; stuckProcessing: number; failedLast24Hours: number; durationAverageMs: number; durationP95Ms: number; sampleSize: number };
  storage: { available: boolean; latencyMs: number; refreshSeconds: number; buckets: Array<{ bucket: string; objects: number; bytes: number; truncated: boolean }> };
  search: { available: boolean; latencyMs: number; databaseBytes: number; lastUpdate: string | null; indexes: Array<{ name: string; documents: number; isIndexing: boolean }>; documents: number; indexing: number };
  cache: { windowMinutes: number; reads: number; hits: number; misses: number; writes: number; errors: number; hitRate: number; p95Ms: number; transferredBytes: number; namespaces: Array<{ namespace: string; reads: number; hitRate: number; writes: number; errors: number }> };
  disks: Array<{ name: string; available: boolean; totalBytes: number; freeBytes: number; freePercent: number }>;
  capacity: { score: number; limitingResource: string; pressures: Array<{ name: string; value: number }>; observationMinutes: number; forecastAvailable: boolean; minutesToCritical: number | null };
  process: { uptimeSeconds: number; cpuPercent: number; rssBytes: number; heapUsedBytes: number; heapTotalBytes: number; eventLoopUtilization: number; eventLoopDelayP95Ms: number; eventLoopDelayMaxMs: number };
  host: { totalMemoryBytes: number; freeMemoryBytes: number; cpuCount: number };
  database: { latencyMs: number; activeConnections: number; totalConnections: number; maxConnections: number; databaseBytes: number };
  product: { accounts: number; communities: number; events: number; pendingJobs: number };
};

const formatBytes = (bytes: number) => {
  if (bytes < 1024 ** 2) return `${Math.round(bytes / 1024)} КБ`;
  if (bytes < 1024 ** 3) return `${(bytes / 1024 ** 2).toFixed(1)} МБ`;
  return `${(bytes / 1024 ** 3).toFixed(1)} ГБ`;
};
const formatUptime = (seconds: number) => seconds >= 86400 ? `${Math.floor(seconds / 86400)} д ${Math.floor(seconds % 86400 / 3600)} ч` : `${Math.floor(seconds / 3600)} ч ${Math.floor(seconds % 3600 / 60)} мин`;
const formatClientValue = (name: ClientMetricName, value: number) => name.endsWith('_BYTES') ? formatBytes(value) : name === 'CLS' ? value.toFixed(3) : name === 'JS_HEAP_USAGE' ? `${value.toFixed(1)}%` : name === 'JS_HEAP_USED_MB' ? `${Math.round(value)} МБ` : name === 'RENDER_RATE' ? `${Math.round(value)}/с` : name === 'REQUEST_BURST' ? `${value.toFixed(1)}/10с` : `${Math.round(value)} мс`;

function MetricCard({ icon, label, value, hint, alert = false }: { icon: ReactNode; label: string; value: string; hint: string; alert?: boolean }) {
  return <View style={[styles.metricCard, alert && styles.metricCardAlert]}><View style={styles.metricTop}><View style={[styles.metricIcon, alert && styles.metricIconAlert]}>{icon}</View><Text style={styles.metricLabel}>{label}</Text></View><Text style={styles.metricValue}>{value}</Text><Text style={styles.metricHint}>{hint}</Text></View>;
}

function StatusRow({ label, detail, latency, inactive = false }: { label: string; detail: string; latency?: number; inactive?: boolean }) {
  const healthy = latency === undefined || latency < 500;
  const isInactive = inactive || (label === 'Socket.IO' && detail === 'Realtime ещё не инициализирован');
  return <View style={styles.statusRow}><View style={[styles.statusDot, !healthy && styles.statusDotWarning, isInactive && styles.statusDotInactive]} /><View style={styles.statusCopy}><Text style={styles.statusLabel}>{label}</Text><Text style={styles.statusDetail}>{detail}</Text></View>{isInactive ? <Text style={styles.statusInactive}>неактивен</Text> : latency !== undefined ? <Text style={styles.statusLatency}>{latency} мс</Text> : <Text style={styles.statusOk}>работает</Text>}</View>;
}

export function AdminPanelScreen() {
  const { width } = useWindowDimensions();
  const compact = width < 820;
  const [account, setAccount] = useState<AdminAccount | null>(null);
  const [state, setState] = useState<LoadState>('loading');
  const [monitoring, setMonitoring] = useState<Monitoring | null>(null);
  const [monitoringError, setMonitoringError] = useState('');
  const [isRefreshing, setIsRefreshing] = useState(false);

  const loadSession = useCallback(async () => {
    setState('loading');
    try {
      const response = await fetch(`${apiUrl}/auth/me`);
      if (response.status === 401) return setState('unauthorized');
      if (!response.ok) return setState('error');
      const { account: current } = await response.json() as { account: AdminAccount };
      setAccount(current);
      setState(current.role === 'ADMIN' ? 'ready' : 'forbidden');
    } catch { setState('error'); }
  }, []);

  const loadMonitoring = useCallback(async (silent = false) => {
    if (!silent) setIsRefreshing(true);
    try {
      const response = await fetch(`${apiUrl}/admin/monitoring`);
      if (!response.ok) throw new Error(await readApiError(response, 'Не удалось получить метрики'));
      setMonitoring(await response.json() as Monitoring);
      setMonitoringError('');
    } catch (error) { setMonitoringError(error instanceof Error ? error.message : 'Не удалось получить метрики'); }
    finally { if (!silent) setIsRefreshing(false); }
  }, []);

  useEffect(() => { void loadSession(); }, [loadSession]);
  useEffect(() => {
    if (state !== 'ready') return;
    void loadMonitoring();
    const timer = setInterval(() => void loadMonitoring(true), 5000);
    return () => clearInterval(timer);
  }, [loadMonitoring, state]);

  const openSocial = () => { if (Platform.OS === 'web' && typeof window !== 'undefined') window.location.assign('/'); };
  const memoryUsed = monitoring ? monitoring.host.totalMemoryBytes - monitoring.host.freeMemoryBytes : 0;
  const memoryPercent = monitoring?.host.totalMemoryBytes ? memoryUsed / monitoring.host.totalMemoryBytes * 100 : 0;
  const maxRequests = useMemo(() => Math.max(1, ...(monitoring?.requests.buckets.map((item) => item.requests) ?? [1])), [monitoring]);
  const sentryConfigured = Boolean(process.env.EXPO_PUBLIC_SENTRY_DSN);
  const clientMetric = (name: Monitoring['client']['metrics'][number]['name']) => monitoring?.client.metrics.find((item) => item.name === name);
  const responseTotals = monitoring?.requests.endpoints.reduce((acc, item) => ({ requests: acc.requests + item.requests, compressed: acc.compressed + item.requests * item.compressedRate }), { requests: 0, compressed: 0 });
  const lowestDisk = monitoring?.disks.filter((disk) => disk.available).sort((a, b) => a.freePercent - b.freePercent)[0];
  const monthlySlo = monitoring?.slo.windows.find((item) => item.range === '30d');
  const hourlySlo = monitoring?.slo.windows.find((item) => item.range === '1h');

  if (state === 'loading') {
    return <SafeAreaView edges={['top', 'bottom']} style={styles.root}><View style={[styles.frame, compact && styles.frameCompact]}><View style={[styles.sidebar, compact && styles.sidebarCompact]}><View style={styles.brandRow}><View style={styles.logoSmall}><ShieldCheck color="#fff" size={20} /></View><View><Text style={styles.wordmarkSmall}>VOLNA</Text><Text style={styles.controlLabel}>CONTROL CENTER</Text></View></View></View><View style={styles.workspace}><View style={styles.topbar}><View><Text style={styles.pageEyebrow}>СИСТЕМА</Text><Text style={styles.pageTitle}>Мониторинг</Text></View><ActivityIndicator color="#111" /></View><View style={styles.loadingContent}><View style={styles.loadingWide} /><View style={styles.metricGrid}>{[0, 1, 2, 3].map((item) => <View key={item} style={styles.loadingMetric} />)}</View><View style={styles.loadingWide} /></View></View></View></SafeAreaView>;
  }

  if (state !== 'ready' || !account) {
    return <SafeAreaView style={styles.gate}><View style={styles.gateCard}><View style={styles.logo}><ShieldCheck color="#fff" size={27} /></View><Text style={styles.wordmark}>VOLNA CONTROL</Text><Text style={styles.gateTitle}>{state === 'unauthorized' ? 'Нужна авторизация' : state === 'forbidden' ? 'Доступ запрещён' : 'Ошибка подключения'}</Text><Text style={styles.gateText}>{state === 'unauthorized' ? 'Войдите в основной VOLNA-аккаунт. Админ-панель использует ту же защищённую сессию.' : state === 'forbidden' ? 'Панель доступна только аккаунту с ролью администратора.' : 'Не удалось проверить текущую сессию.'}</Text><Pressable onPress={state === 'error' ? () => void loadSession() : openSocial} style={styles.gateButton}><Text style={styles.gateButtonText}>{state === 'error' ? 'Повторить' : 'Открыть VOLNA'}</Text></Pressable></View></SafeAreaView>;
  }

  return <SafeAreaView edges={['top', 'bottom']} style={styles.root}>
    <View style={[styles.frame, compact && styles.frameCompact]}>
      <View style={[styles.sidebar, compact && styles.sidebarCompact]}>
        <View style={styles.brandRow}><View style={styles.logoSmall}><ShieldCheck color="#fff" size={20} /></View><View><Text style={styles.wordmarkSmall}>VOLNA</Text><Text style={styles.controlLabel}>CONTROL CENTER</Text></View></View>
        <View style={[styles.navigation, compact && styles.navigationCompact]}>
          <View style={styles.navActive}><Gauge color="#fff" size={18} /><Text style={styles.navActiveText}>Мониторинг</Text></View>
          <View style={styles.navDisabled}><UsersRound color="#6f7b86" size={18} /><Text style={styles.navDisabledText}>Управление</Text></View>
          <View style={styles.navDisabled}><AlertTriangle color="#6f7b86" size={18} /><Text style={styles.navDisabledText}>Модерация</Text></View>
        </View>
        {!compact ? <View style={styles.sidebarFooter}><Text style={styles.accountName}>{account.name}</Text><Text style={styles.accountUsername}>@{account.username}</Text><Pressable onPress={openSocial} style={styles.openProduct}><Text style={styles.openProductText}>Открыть VOLNA</Text><ArrowUpRight color="#111" size={15} /></Pressable></View> : null}
      </View>

      <View style={styles.workspace}>
        <View style={styles.topbar}><View><Text style={styles.pageEyebrow}>СИСТЕМА</Text><Text style={styles.pageTitle}>Мониторинг</Text></View><View style={styles.topbarActions}><View style={styles.livePill}><View style={styles.liveDot} /><Text style={styles.liveText}>LIVE · 5 сек</Text></View><Pressable accessibilityLabel="Обновить показатели" onPress={() => void loadMonitoring()} style={styles.refreshButton}>{isRefreshing ? <ActivityIndicator color="#111" size="small" /> : <RefreshCw color="#111" size={18} />}</Pressable></View></View>
        <ScrollView contentContainerStyle={styles.content} showsVerticalScrollIndicator={false}>
          {monitoringError ? <View style={styles.errorBanner}><AlertTriangle color="#b42318" size={18} /><Text style={styles.errorText}>{monitoringError}</Text></View> : null}
          <View style={styles.attentionCard}>
            <View style={styles.cardHeader}><View><Text style={styles.cardTitle}>Требует внимания</Text><Text style={styles.cardSubtitle}>Автоматический разбор фактических HTTP- и SQL-метрик</Text></View><AlertTriangle color={monitoring?.analysis.issues.length ? '#b42318' : '#23813d'} size={21} /></View>
            {monitoring?.alerts.items.map((alert) => <View key={alert.name} style={[styles.liveAlert, alert.severity === 'critical' && styles.liveAlertCritical]}><View style={styles.liveAlertHeader}><Text style={styles.liveAlertState}>{alert.state === 'firing' ? 'СРАБОТАЛ' : 'ОЖИДАНИЕ'} · {alert.severity === 'critical' ? 'КРИТИЧНО' : 'ПРЕДУПРЕЖДЕНИЕ'}</Text><Text style={styles.liveAlertName}>{alert.name}</Text></View><Text style={styles.liveAlertSummary}>{alert.summary}</Text></View>)}
            {monitoring?.analysis.issues.length ? monitoring.analysis.issues.map((issue) => <View key={issue.id} style={styles.issueRow}><View style={[styles.issuePill, issue.severity === 'critical' ? styles.issueCritical : issue.severity === 'warning' ? styles.issueWarning : styles.issueOpportunity]}><Text style={styles.issuePillText}>{issue.severity === 'critical' ? 'КРИТИЧНО' : issue.severity === 'warning' ? 'ПРОВЕРИТЬ' : 'ОПТИМИЗАЦИЯ'}</Text></View><View style={styles.issueCopy}><Text style={styles.issueTitle}>{issue.title}</Text><Text style={styles.issueEvidence}>{issue.evidence}</Text><Text style={styles.issueRecommendation}>{issue.recommendation}</Text></View><Text style={styles.confidence}>{issue.confidence === 'high' ? 'высокая уверенность' : 'средняя уверенность'}</Text></View>) : <View style={styles.noIssues}><ShieldCheck color="#23813d" size={20} /><View><Text style={styles.noIssuesTitle}>Подтверждённых отклонений пока нет</Text><Text style={styles.noIssuesText}>Система продолжает собирать baseline. Сигналы появятся только после достаточного числа запросов.</Text></View></View>}
            <Text style={styles.windowNote}>{monitoring?.analysis.windowNote ?? 'HTTP: последние 5 минут. SQL: накопительная статистика.'}</Text>
          </View>
          <View style={styles.metricGrid}>
            <MetricCard icon={<Activity color="#111" size={19} />} label="Запросы" value={`${monitoring?.requests.rpm ?? 0}/мин`} hint={`${monitoring?.requests.active ?? 0} выполняется сейчас`} />
            <MetricCard alert={Boolean(monitoring && monitoring.requests.errorRate > 0.05)} icon={<AlertTriangle color={monitoring && monitoring.requests.errorRate > 0.05 ? '#b42318' : '#111'} size={19} />} label="Ошибки 5xx" value={`${((monitoring?.requests.errorRate ?? 0) * 100).toFixed(1)}%`} hint={`${monitoring?.requests.errorsLastFiveMinutes ?? 0} за последние 5 минут`} />
            <MetricCard icon={<Clock3 color="#111" size={19} />} label="Задержка p95" value={`${monitoring?.requests.p95Ms ?? 0} мс`} hint={`p50 ${monitoring?.requests.p50Ms ?? 0} · p99 ${monitoring?.requests.p99Ms ?? 0} мс`} />
            <MetricCard icon={<Cpu color="#111" size={19} />} label="CPU процесса" value={`${monitoring?.process.cpuPercent ?? 0}%`} hint={`${monitoring?.host.cpuCount ?? 0} логических ядер`} />
          </View>

          <View style={styles.metricGrid}>
            <MetricCard alert={Boolean(monthlySlo?.availability !== null && monthlySlo && monthlySlo.availability < (monitoring?.slo.objective ?? 0.995))} icon={<ShieldCheck color="#111" size={19} />} label="Доступность · 30 дней" value={monthlySlo?.availability === null || !monthlySlo ? '—' : `${(monthlySlo.availability * 100).toFixed(3)}%`} hint={`цель ${((monitoring?.slo.objective ?? 0.995) * 100).toFixed(1)}%`} />
            <MetricCard alert={Boolean(monthlySlo && monthlySlo.budgetRemainingPercent < 25)} icon={<Gauge color="#111" size={19} />} label="Остаток error budget" value={monthlySlo ? `${monthlySlo.budgetRemainingPercent.toFixed(1)}%` : '—'} hint="допустимый запас ошибок за 30 дней" />
            <MetricCard alert={Boolean(monthlySlo?.latencyCompliance !== null && monthlySlo && monthlySlo.latencyCompliance < (monitoring?.slo.latencyObjective ?? 0.95))} icon={<Clock3 color="#111" size={19} />} label="Быстрее 500 мс · 30 дней" value={monthlySlo?.latencyCompliance === null || !monthlySlo ? '—' : `${(monthlySlo.latencyCompliance * 100).toFixed(2)}%`} hint={`цель ${((monitoring?.slo.latencyObjective ?? 0.95) * 100).toFixed(0)}% запросов`} />
            <MetricCard alert={Boolean(hourlySlo && hourlySlo.burnRate >= 6)} icon={<AlertTriangle color="#111" size={19} />} label="Скорость сгорания · 1 час" value={hourlySlo ? `${hourlySlo.burnRate.toFixed(2)}×` : '—'} hint="выше 1× — бюджет расходуется быстрее нормы" />
          </View>

          <View style={[styles.twoColumns, compact && styles.oneColumn]}>
            <View style={styles.largeCard}><View style={styles.cardHeader}><View><Text style={styles.cardTitle}>SLI / SLO</Text><Text style={styles.cardSubtitle}>Доступность, задержка и расход error budget · хранение {monitoring?.slo.retentionDays ?? 30} дней</Text></View><ShieldCheck color={monitoring?.slo.available ? '#23813d' : '#b42318'} size={21} /></View><View style={styles.tableHeader}><Text style={[styles.tableHeaderText, styles.endpointColumn]}>ОКНО</Text><Text style={styles.tableHeaderText}>ЗАПРОСЫ</Text><Text style={styles.tableHeaderText}>ДОСТУП.</Text><Text style={styles.tableHeaderText}>BURN</Text></View>{monitoring?.slo.windows.length ? monitoring.slo.windows.map((item) => <View key={item.range} style={styles.tableRow}><View style={styles.endpointColumn}><Text style={styles.endpointName}>{item.label}</Text><Text style={styles.endpointErrors}>≤ {monitoring.slo.latencyTargetMs} мс: {item.latencyCompliance === null ? '—' : `${(item.latencyCompliance * 100).toFixed(2)}%`} · бюджет: {item.budgetRemainingPercent.toFixed(1)}%</Text></View><Text style={styles.tableValue}>{item.samples}</Text><Text style={styles.tableValue}>{item.availability === null ? '—' : `${(item.availability * 100).toFixed(3)}%`}</Text><Text style={styles.tableValue}>{item.burnRate.toFixed(2)}×</Text></View>) : <Text style={styles.emptyText}>Prometheus пока не вернул данные SLO.</Text>}</View>
            <View style={styles.healthCard}><View style={styles.cardHeader}><View><Text style={styles.cardTitle}>История инцидентов</Text><Text style={styles.cardSubtitle}>Сработавшие системные алерты за 7 дней</Text></View><AlertTriangle color="#6f7b86" size={21} /></View>{monitoring?.slo.incidents.length ? monitoring.slo.incidents.map((incident) => <View key={`${incident.name}-${incident.startedAt}`} style={styles.incidentRow}><View style={[styles.incidentDot, incident.severity === 'critical' && styles.incidentDotCritical]} /><View style={styles.issueCopy}><Text style={styles.endpointName}>{incident.name}</Text><Text style={styles.endpointErrors}>{new Date(incident.startedAt).toLocaleString('ru-RU')} · {incident.durationMinutes} мин · {incident.endedAt ? 'завершён' : 'активен'}</Text></View></View>) : <Text style={styles.emptyText}>Инцидентов за 7 дней нет.</Text>}</View>
          </View>

          <View style={styles.metricGrid}>
            <MetricCard alert={Boolean((monitoring?.process.eventLoopDelayP95Ms ?? 0) >= 100)} icon={<Activity color="#111" size={19} />} label="Event-loop lag · p95" value={`${monitoring?.process.eventLoopDelayP95Ms ?? 0} мс`} hint={`максимум ${monitoring?.process.eventLoopDelayMaxMs ?? 0} мс`} />
            <MetricCard alert={Boolean((monitoring?.process.eventLoopUtilization ?? 0) >= 80)} icon={<Cpu color="#111" size={19} />} label="Event-loop utilization" value={`${monitoring?.process.eventLoopUtilization ?? 0}%`} hint="Доля времени, когда главный поток Node.js занят" />
            <MetricCard alert={Boolean(lowestDisk && lowestDisk.freePercent < 10 && lowestDisk.freeBytes < 20 * 1024 ** 3)} icon={<HardDrive color="#111" size={19} />} label="Свободное место" value={lowestDisk ? formatBytes(lowestDisk.freeBytes) : '—'} hint={lowestDisk ? `${lowestDisk.freePercent.toFixed(1)}% · диск ${lowestDisk.name}` : 'Файловая система недоступна'} />
            <MetricCard alert={Boolean(monitoring && monitoring.capacity.score < 20)} icon={<Gauge color="#111" size={19} />} label="Запас мощности" value={`${monitoring?.capacity.score ?? 0}%`} hint={monitoring?.capacity.forecastAvailable ? `до критического уровня ≈ ${monitoring.capacity.minutesToCritical} мин` : `${monitoring?.capacity.limitingResource ?? 'нет данных'} · наблюдение ${monitoring?.capacity.observationMinutes ?? 0} мин`} />
          </View>

          <View style={styles.metricGrid}>
            <MetricCard alert={Boolean(clientMetric('LCP')?.poor)} icon={<Gauge color="#111" size={19} />} label="LCP · p75" value={clientMetric('LCP')?.samples ? `${Math.round(clientMetric('LCP')!.p75)} мс` : '—'} hint={`${clientMetric('LCP')?.samples ?? 0} замеров · ${clientMetric('LCP')?.poor ?? 0} плохих`} />
            <MetricCard alert={Boolean(clientMetric('INP')?.poor)} icon={<Gauge color="#111" size={19} />} label="INP · p75" value={clientMetric('INP')?.samples ? `${Math.round(clientMetric('INP')!.p75)} мс` : '—'} hint={`${clientMetric('INP')?.samples ?? 0} замеров · ${clientMetric('INP')?.poor ?? 0} плохих`} />
            <MetricCard alert={Boolean(clientMetric('CLS')?.poor)} icon={<Gauge color="#111" size={19} />} label="CLS · p75" value={clientMetric('CLS')?.samples ? clientMetric('CLS')!.p75.toFixed(3) : '—'} hint={`${clientMetric('CLS')?.samples ?? 0} замеров · ${clientMetric('CLS')?.poor ?? 0} плохих`} />
            <MetricCard alert={Boolean(clientMetric('API_DURATION')?.poor)} icon={<Clock3 color="#111" size={19} />} label="Клиентский API · p75" value={clientMetric('API_DURATION')?.samples ? `${Math.round(clientMetric('API_DURATION')!.p75)} мс` : '—'} hint={`${clientMetric('API_DURATION')?.samples ?? 0} замеров · последние ${monitoring?.client.windowMinutes ?? 15} мин`} />
            <MetricCard alert={Boolean(clientMetric('LONG_TASK')?.poor)} icon={<Cpu color="#111" size={19} />} label="Long Tasks · p75" value={clientMetric('LONG_TASK')?.samples ? `${Math.round(clientMetric('LONG_TASK')!.p75)} мс` : '—'} hint={`${clientMetric('LONG_TASK')?.samples ?? 0} блокировок · ${clientMetric('LONG_TASK')?.poor ?? 0} тяжёлых`} />
            <MetricCard alert={Boolean(clientMetric('JS_HEAP_USAGE')?.poor)} icon={<MemoryStick color="#111" size={19} />} label="JS heap" value={clientMetric('JS_HEAP_USED_MB')?.samples ? `${Math.round(clientMetric('JS_HEAP_USED_MB')!.p75)} МБ` : '—'} hint={clientMetric('JS_HEAP_USAGE')?.samples ? `${clientMetric('JS_HEAP_USAGE')!.p75.toFixed(1)}% лимита · p75` : 'Браузер пока не передал память'} />
            <MetricCard alert={Boolean(clientMetric('IMAGE_TRANSFER_BYTES')?.poor)} icon={<HardDrive color="#111" size={19} />} label="Изображения · p75" value={clientMetric('IMAGE_TRANSFER_BYTES')?.samples ? formatBytes(clientMetric('IMAGE_TRANSFER_BYTES')!.p75) : '—'} hint={`${clientMetric('IMAGE_TRANSFER_BYTES')?.samples ?? 0} ресурсов · ${clientMetric('IMAGE_TRANSFER_BYTES')?.poor ?? 0} тяжёлых`} />
            <MetricCard alert={Boolean(clientMetric('SCRIPT_TRANSFER_BYTES')?.poor)} icon={<HardDrive color="#111" size={19} />} label="JS-ресурсы · p75" value={clientMetric('SCRIPT_TRANSFER_BYTES')?.samples ? formatBytes(clientMetric('SCRIPT_TRANSFER_BYTES')!.p75) : '—'} hint={`${clientMetric('SCRIPT_TRANSFER_BYTES')?.samples ?? 0} ресурсов · dev и production учитываются отдельно по факту`} />
            <MetricCard icon={<Gauge color="#111" size={19} />} label="Сжатие API" value={responseTotals?.requests ? `${Math.round(responseTotals.compressed / responseTotals.requests * 100)}%` : '—'} hint="gzip для ответов от 1 КБ · последние 5 минут" />
          </View>

          <View style={[styles.twoColumns, compact && styles.oneColumn]}>
            <View style={styles.largeCard}><View style={styles.cardHeader}><View><Text style={styles.cardTitle}>HTTP-нагрузка</Text><Text style={styles.cardSubtitle}>Запросы и ошибки по минутам · последние 15 минут</Text></View><Text style={styles.cardTimestamp}>{monitoring ? new Date(monitoring.generatedAt).toLocaleTimeString('ru-RU') : '—'}</Text></View><View style={styles.chart}>{monitoring?.requests.buckets.map((bucket) => <View key={bucket.at} style={styles.barColumn}><View style={styles.barArea}><View style={[styles.bar, { height: Math.max(3, bucket.requests / maxRequests * 122) }]}>{bucket.errors ? <View style={[styles.errorBar, { height: Math.max(3, bucket.errors / Math.max(1, bucket.requests) * 100) + '%' as never }]} /> : null}</View></View><Text style={styles.barLabel}>{new Date(bucket.at).getMinutes().toString().padStart(2, '0')}</Text></View>)}</View><View style={styles.legend}><View style={styles.legendItem}><View style={styles.legendBlack} /><Text style={styles.legendText}>Все запросы</Text></View><View style={styles.legendItem}><View style={styles.legendRed} /><Text style={styles.legendText}>5xx</Text></View></View></View>
            <View style={styles.healthCard}><View style={styles.cardHeader}><View><Text style={styles.cardTitle}>Сервисы</Text><Text style={styles.cardSubtitle}>Текущее состояние контура</Text></View><Server color="#6f7b86" size={21} /></View><StatusRow label="API / NestJS" detail={`Uptime ${formatUptime(monitoring?.process.uptimeSeconds ?? 0)}`} /><StatusRow label="PostgreSQL" detail={`${monitoring?.database.totalConnections ?? 0} из ${monitoring?.database.maxConnections ?? 0} соединений`} latency={monitoring?.database.latencyMs ?? 0} /><StatusRow label="PostgreSQL Outbox" detail={monitoring?.infrastructure.outbox.listenerConnected ? `LISTEN активен · ${monitoring.infrastructure.outbox.notificationCount} уведомлений · ${monitoring.infrastructure.outbox.fallbackRuns} fallback` : 'LISTEN недоступен · fallback раз в минуту'} latency={monitoring?.infrastructure.outbox.listenerConnected ? 0 : 999} /><StatusRow label="Redis / BullMQ" detail={monitoring?.infrastructure.available ? `${monitoring.infrastructure.queue.workers} worker · ${monitoring.infrastructure.queue.waiting} ожидают` : 'Сервис недоступен'} latency={monitoring?.infrastructure.available ? monitoring.infrastructure.latencyMs : 999} /><StatusRow label="Object storage / S3" detail={monitoring?.storage.available ? `${monitoring.storage.buckets.reduce((sum, item) => sum + item.objects, 0)} объектов` : 'Хранилище недоступно'} latency={monitoring?.storage.available ? monitoring.storage.latencyMs : 999} /><StatusRow label="Meilisearch" detail={monitoring?.search.available ? `${monitoring.search.documents} документов · ${monitoring.search.indexes.length} индексов` : 'Поиск недоступен'} latency={monitoring?.search.available ? monitoring.search.latencyMs : 999} /><StatusRow label="Socket.IO" detail={monitoring?.infrastructure.realtime.available ? `${monitoring.infrastructure.realtime.connections} соединений · ${monitoring.infrastructure.realtime.rooms} комнат` : 'Realtime ещё не инициализирован'} latency={monitoring?.infrastructure.realtime.available ? 0 : 999} /><StatusRow label="Prometheus / Alertmanager" detail={monitoring?.alerts.available ? `${monitoring.alerts.firing} активных · ${monitoring.alerts.pending} ожидают подтверждения` : 'Сервис алертов недоступен'} latency={monitoring?.alerts.available ? 0 : 999} /><StatusRow label="Loki / Alloy" detail={monitoring?.logs.available ? `${monitoring.logs.services.length} источника · хранение ${monitoring.logs.retentionDays} дней` : 'Централизованные логи недоступны'} latency={monitoring?.logs.available ? 0 : 999} /><StatusRow label="Tempo / OpenTelemetry" detail={monitoring?.traces.available ? `${monitoring.traces.recentTraces} последних трасс · хранение ${monitoring.traces.retentionDays} дней` : 'Трассировки недоступны'} latency={monitoring?.traces.available ? 0 : 999} /><StatusRow label="Sentry / клиент" detail={sentryConfigured ? 'Ошибки Expo, iOS, Android и PWA подключены' : 'DSN не настроен'} latency={sentryConfigured ? 0 : 999} /><StatusRow label="Cloudflare Tunnel" detail="Панель доступна через публичный контур" /></View>
          </View>

          <View style={styles.metricGrid}>
            <MetricCard alert={Boolean((monitoring?.infrastructure.queue.waiting ?? 0) >= 20)} icon={<Activity color="#111" size={19} />} label="Очередь BullMQ" value={`${monitoring?.infrastructure.queue.waiting ?? 0}`} hint={`${monitoring?.infrastructure.queue.active ?? 0} активных · ${monitoring?.infrastructure.queue.delayed ?? 0} отложено`} />
            <MetricCard alert={Boolean(monitoring?.infrastructure.queue.failedLast24Hours)} icon={<AlertTriangle color="#111" size={19} />} label="Ошибки worker · 24ч" value={`${monitoring?.infrastructure.queue.failedLast24Hours ?? 0}`} hint={`p95 задания ${monitoring?.infrastructure.queue.durationP95Ms ?? 0} мс`} />
            <MetricCard alert={Boolean(monitoring?.infrastructure.redis.evictedKeys)} icon={<Database color="#111" size={19} />} label="Redis memory" value={formatBytes(monitoring?.infrastructure.redis.memoryUsedBytes ?? 0)} hint={`пик ${formatBytes(monitoring?.infrastructure.redis.memoryPeakBytes ?? 0)} · ${monitoring?.infrastructure.redis.evictedKeys ?? 0} eviction`} />
            <MetricCard alert={Boolean(monitoring?.media.stuckProcessing || monitoring?.media.failedLast24Hours)} icon={<HardDrive color="#111" size={19} />} label="Обработка аудио" value={`${monitoring?.media.processing ?? 0}`} hint={`${monitoring?.media.stuckProcessing ?? 0} зависло · p95 ${monitoring?.media.durationP95Ms ?? 0} мс`} />
          </View>

          <View style={styles.metricGrid}>
            <MetricCard alert={Boolean(monitoring && !monitoring.storage.available)} icon={<HardDrive color="#111" size={19} />} label="S3 storage" value={formatBytes(monitoring?.storage.buckets.reduce((sum, item) => sum + item.bytes, 0) ?? 0)} hint={`${monitoring?.storage.buckets.reduce((sum, item) => sum + item.objects, 0) ?? 0} объектов · обновление ${monitoring?.storage.refreshSeconds ?? 60}с`} />
            <MetricCard alert={Boolean(monitoring && !monitoring.search.available)} icon={<Database color="#111" size={19} />} label="Meilisearch" value={`${monitoring?.search.documents ?? 0}`} hint={`${formatBytes(monitoring?.search.databaseBytes ?? 0)} · ${monitoring?.search.indexing ?? 0} индексируется`} />
            <MetricCard alert={Boolean(monitoring && monitoring.cache.reads >= 20 && monitoring.cache.hitRate < 0.25)} icon={<Gauge color="#111" size={19} />} label="Redis cache hit rate" value={monitoring?.cache.reads ? `${Math.round(monitoring.cache.hitRate * 100)}%` : '—'} hint={`${monitoring?.cache.hits ?? 0} hit · ${monitoring?.cache.misses ?? 0} miss · p95 ${monitoring?.cache.p95Ms ?? 0} мс`} />
            <MetricCard alert={Boolean(monitoring?.cache.errors)} icon={<Activity color="#111" size={19} />} label="Cache traffic" value={formatBytes(monitoring?.cache.transferredBytes ?? 0)} hint={`${monitoring?.cache.writes ?? 0} записей · ${monitoring?.cache.errors ?? 0} ошибок`} />
          </View>

          <View style={[styles.twoColumns, compact && styles.oneColumn]}>
            <View style={styles.smallCard}><View style={styles.cardHeader}><View><Text style={styles.cardTitle}>S3 buckets</Text><Text style={styles.cardSubtitle}>Подсчёт ограничен 10 000 объектами на bucket и кэшируется на минуту</Text></View><HardDrive color="#6f7b86" size={21} /></View>{monitoring?.storage.buckets.map((bucket) => <View key={bucket.bucket} style={styles.resourceRow}><Text style={styles.resourceLabel}>{bucket.bucket}{bucket.truncated ? ' (частично)' : ''}</Text><Text style={styles.resourceValue}>{bucket.objects} · {formatBytes(bucket.bytes)}</Text></View>)}</View>
            <View style={styles.smallCard}><View style={styles.cardHeader}><View><Text style={styles.cardTitle}>Кэш по namespace</Text><Text style={styles.cardSubtitle}>Только агрегаты ключей, без поисковых строк и идентификаторов</Text></View><Gauge color="#6f7b86" size={21} /></View>{monitoring?.cache.namespaces.length ? monitoring.cache.namespaces.map((item) => <View key={item.namespace} style={styles.resourceRow}><Text style={styles.resourceLabel}>{item.namespace} · {item.reads} чт.</Text><Text style={styles.resourceValue}>{Math.round(item.hitRate * 100)}% hit · {item.errors} err</Text></View>) : <Text style={styles.emptyText}>Кэш-операций за 15 минут пока нет.</Text>}</View>
          </View>

          <View style={[styles.twoColumns, compact && styles.oneColumn]}>
            <View style={styles.largeCard}><View style={styles.cardHeader}><View><Text style={styles.cardTitle}>Самые активные endpoints</Text><Text style={styles.cardSubtitle}>Задержка, повторы и фактический размер после сжатия · последние 5 минут</Text></View><Activity color="#6f7b86" size={21} /></View><View style={styles.tableHeader}><Text style={[styles.tableHeaderText, styles.endpointColumn]}>МАРШРУТ</Text><Text style={styles.tableHeaderText}>ЗАПРОСЫ</Text><Text style={styles.tableHeaderText}>СРЕД.</Text><Text style={styles.tableHeaderText}>P95</Text></View>{monitoring?.requests.endpoints.length ? monitoring.requests.endpoints.map((item) => <View key={`${item.method}-${item.route}`} style={styles.tableRow}><View style={styles.endpointColumn}><Text numberOfLines={1} style={styles.endpointName}><Text style={styles.method}>{item.method} </Text>{item.route}</Text><Text style={styles.endpointErrors}>{item.errors ? `${item.errors} ошибок` : 'без 5xx'} · {item.duplicateRequests ? `${item.duplicateRequests} повторов` : 'повторов нет'} · ответ p95 {formatBytes(item.p95Bytes)} · gzip {Math.round(item.compressedRate * 100)}%</Text></View><Text style={styles.tableValue}>{item.requests}</Text><Text style={styles.tableValue}>{item.averageMs} мс</Text><Text style={styles.tableValue}>{item.p95Ms} мс</Text></View>) : <Text style={styles.emptyText}>Метрики появятся после первых запросов к API.</Text>}</View>
            <View style={styles.stackColumn}><View style={styles.smallCard}><View style={styles.cardHeader}><View><Text style={styles.cardTitle}>Ресурсы</Text><Text style={styles.cardSubtitle}>Текущий процесс и хост</Text></View><MemoryStick color="#6f7b86" size={21} /></View><View style={styles.resourceRow}><Text style={styles.resourceLabel}>RAM хоста</Text><Text style={styles.resourceValue}>{formatBytes(memoryUsed)} / {formatBytes(monitoring?.host.totalMemoryBytes ?? 0)}</Text></View><View style={styles.progress}><View style={[styles.progressFill, { width: `${Math.min(100, memoryPercent)}%` }]} /></View><View style={styles.resourceRow}><Text style={styles.resourceLabel}>Node RSS</Text><Text style={styles.resourceValue}>{formatBytes(monitoring?.process.rssBytes ?? 0)}</Text></View><View style={styles.resourceRow}><Text style={styles.resourceLabel}>Node heap</Text><Text style={styles.resourceValue}>{formatBytes(monitoring?.process.heapUsedBytes ?? 0)} / {formatBytes(monitoring?.process.heapTotalBytes ?? 0)}</Text></View><View style={styles.resourceRow}><Text style={styles.resourceLabel}>База данных</Text><Text style={styles.resourceValue}>{formatBytes(monitoring?.database.databaseBytes ?? 0)}</Text></View></View><View style={styles.smallCard}><View style={styles.cardHeader}><View><Text style={styles.cardTitle}>VOLNA сегодня</Text><Text style={styles.cardSubtitle}>Размер продуктовых данных</Text></View><HardDrive color="#6f7b86" size={21} /></View><View style={styles.productGrid}><View><Text style={styles.productValue}>{monitoring?.product.accounts ?? '—'}</Text><Text style={styles.productLabel}>аккаунтов</Text></View><View><Text style={styles.productValue}>{monitoring?.product.communities ?? '—'}</Text><Text style={styles.productLabel}>сообществ</Text></View><View><Text style={styles.productValue}>{monitoring?.product.events ?? '—'}</Text><Text style={styles.productLabel}>событий</Text></View><View><Text style={styles.productValue}>{monitoring?.database.activeConnections ?? '—'}</Text><Text style={styles.productLabel}>активных SQL</Text></View></View></View></View>
          </View>
          <View style={[styles.twoColumns, compact && styles.oneColumn]}>
            <View style={styles.largeCard}><View style={styles.cardHeader}><View><Text style={styles.cardTitle}>Клиентские метрики по экранам</Text><Text style={styles.cardSubtitle}>Web Vitals, ререндеры, request burst, FPS, Long Tasks и JS-память · последние 15 минут</Text></View><Gauge color="#6f7b86" size={21} /></View><View style={styles.tableHeader}><Text style={[styles.tableHeaderText, styles.endpointColumn]}>ЭКРАН / МЕТРИКА</Text><Text style={styles.tableHeaderText}>ЗАМЕРЫ</Text><Text style={styles.tableHeaderText}>P75</Text><Text style={styles.tableHeaderText}>ПЛОХИЕ</Text></View>{monitoring?.client.screens.length ? monitoring.client.screens.map((item) => <View key={`${item.screen}-${item.name}-${item.detail ?? ''}`} style={styles.tableRow}><View style={styles.endpointColumn}><Text style={styles.endpointName}>{item.screen}</Text><Text numberOfLines={1} style={styles.endpointErrors}>{item.name}{item.detail ? ` · ${item.detail}` : ''}</Text></View><Text style={styles.tableValue}>{item.samples}</Text><Text style={styles.tableValue}>{formatClientValue(item.name, item.p75)}</Text><Text style={styles.tableValue}>{item.poor}</Text></View>) : <Text style={styles.emptyText}>Клиентские замеры появятся после открытий PWA.</Text>}</View>
            <View style={styles.largeCard}><View style={styles.cardHeader}><View><Text style={styles.cardTitle}>API глазами клиента</Text><Text style={styles.cardSubtitle}>Сеть, Cloudflare и сервер вместе · без URL-параметров и идентификаторов</Text></View><Clock3 color="#6f7b86" size={21} /></View><View style={styles.tableHeader}><Text style={[styles.tableHeaderText, styles.endpointColumn]}>МАРШРУТ</Text><Text style={styles.tableHeaderText}>ЗАМЕРЫ</Text><Text style={styles.tableHeaderText}>P75</Text><Text style={styles.tableHeaderText}>P95</Text></View>{monitoring?.client.apiRoutes.length ? monitoring.client.apiRoutes.map((item) => <View key={item.route} style={styles.tableRow}><View style={styles.endpointColumn}><Text numberOfLines={1} style={styles.endpointName}>{item.route}</Text><Text style={styles.endpointErrors}>{item.errors ? `${item.errors} ошибок` : 'без ошибок'} · экран {item.topScreen}</Text></View><Text style={styles.tableValue}>{item.samples}</Text><Text style={styles.tableValue}>{item.p75Ms} мс</Text><Text style={styles.tableValue}>{item.p95Ms} мс</Text></View>) : <Text style={styles.emptyText}>Маршрутные замеры появятся после запросов из PWA.</Text>}</View>
          </View>
          <View style={styles.largeCard}><View style={styles.cardHeader}><View><Text style={styles.cardTitle}>Нагрузка PostgreSQL</Text><Text style={styles.cardSubtitle}>Запросы с наибольшим суммарным временем по pg_stat_statements</Text></View><Database color="#6f7b86" size={21} /></View>{monitoring?.analysis.sqlQueries.length ? monitoring.analysis.sqlQueries.map((item) => { const blocks = item.sharedHits + item.sharedReads; const hitRate = blocks ? item.sharedHits / blocks * 100 : 100; return <View key={item.queryId} style={styles.sqlRow}><Text numberOfLines={2} style={styles.sqlQuery}>{item.query}</Text><View style={styles.sqlStats}><Text style={styles.sqlStat}>{item.calls} выз.</Text><Text style={styles.sqlStat}>{item.totalMs.toFixed(0)} мс всего</Text><Text style={styles.sqlStat}>{item.meanMs.toFixed(1)} мс сред.</Text><Text style={styles.sqlStat}>cache {hitRate.toFixed(1)}%</Text></View></View>; }) : <Text style={styles.emptyText}>Статистика SQL появится после включения расширения и первых запросов.</Text>}</View>
          <View style={styles.largeCard}><View style={styles.cardHeader}><View><Text style={styles.cardTitle}>Диагностический журнал</Text><Text style={styles.cardSubtitle}>5xx и запросы дольше 800 мс · последние 15 минут</Text></View><Clock3 color="#6f7b86" size={21} /></View>{monitoring?.requests.diagnosticRequests.length ? monitoring.requests.diagnosticRequests.map((item) => <View key={`${item.requestId}-${item.at}`} style={styles.diagnosticRow}><View style={[styles.statusCode, item.status >= 500 && styles.statusCodeError]}><Text style={styles.statusCodeText}>{item.status}</Text></View><View style={styles.issueCopy}><Text style={styles.diagnosticRoute}><Text style={styles.method}>{item.method} </Text>{item.route}</Text><Text style={styles.diagnosticMeta}>{new Date(item.occurredAt).toLocaleTimeString('ru-RU')} · {item.durationMs.toFixed(0)} мс · экран {item.screen}</Text><Text selectable style={styles.requestId}>requestId: {item.requestId}</Text></View></View>) : <Text style={styles.emptyText}>Ошибок 5xx и запросов дольше 800 мс за последние 15 минут нет.</Text>}</View>
          <Text style={styles.privacyNote}>Метрики не содержат токены, cookie, тексты сообщений, поисковые запросы или персональные данные пользователей.</Text>
        </ScrollView>
      </View>
    </View>
  </SafeAreaView>;
}

