  issueCritical: { backgroundColor: '#fee4e2' }, issueWarning: { backgroundColor: '#fff1cc' }, issueOpportunity: { backgroundColor: '#e8eef8' },
  issuePillText: { color: '#323a43', fontSize: 8, fontWeight: '800' }, issueCopy: { flex: 1, minWidth: 0 }, issueTitle: { color: '#111', fontSize: 13, fontWeight: '700' },
  issueEvidence: { marginTop: 4, color: '#53606c', fontSize: 11, lineHeight: 16 }, issueRecommendation: { marginTop: 5, color: '#6f7b86', fontSize: 10, lineHeight: 15 }, confidence: { color: '#8e99a4', fontSize: 8 },
